// The regx styles a pattern can be written in (amcdb.regxstyle).
export type RegxStyle = 'acr' | 'default' | 'shell' | 'sql'

// True when C is ASCII punctuation, which the canonical regx syntax escapes
// when it means itself.
export function regxPunctQ(c: string): boolean {
    return (c >= '!' && c <= '/') || (c >= ':' && c <= '@') || (c >= '[' && c <= '`') || (c >= '{' && c <= '~')
}

// True when \C is an escape that stands for a class of characters
// (amcdb.regxmacro).
export function regxMacroQ(c: string): boolean {
    let ret = false;
    switch (c) {
        case 'D':
        case 'S':
        case 'W':
        case 'a':
        case 'd':
        case 'e':
        case 'f':
        case 'n':
        case 'r':
        case 's':
        case 't':
        case 'v':
        case 'w':
        ret = true;
        break;
        default:
        break;
    }
    return ret
}

// The JavaScript class escape \C stands for: its body when INCLASS, and a
// bracketed class otherwise.  An empty string when \C is no such escape.
export function regxMacroJs(c: string, inclass: boolean): string {
    let ret = ''
    switch (c) {
    case 'D':
        ret = '\\x00-\\x2f\\x3a-\\uffff'
        break
    case 'S':
        ret = '\\x00-\\x08\\x0e-\\x1f\\x21-\\uffff'
        break
    case 'W':
        ret = '\\x00-\\x2f\\x3a-\\x40\\x5b-\\x5e\\x60\\x7b-\\uffff'
        break
    case 'a':
        ret = '\\x07'
        break
    case 'd':
        ret = '\\x30-\\x39'
        break
    case 'e':
        ret = '\\x1b'
        break
    case 'f':
        ret = '\\x0c'
        break
    case 'n':
        ret = '\\x0a'
        break
    case 'r':
        ret = '\\x0d'
        break
    case 's':
        ret = '\\x09-\\x0d\\x20'
        break
    case 't':
        ret = '\\x09'
        break
    case 'v':
        ret = '\\x0b'
        break
    case 'w':
        ret = '\\x30-\\x39\\x41-\\x5a\\x5f\\x61-\\x7a'
        break
    }
    return inclass || ret === '' ? ret : '[' + ret + ']'
}

// STR, a pattern of regx style STYLE, in the default syntax (amcdb.regxrule).
export function regxRewrite(str: string, style: RegxStyle): string {
    let out = ''
    switch (style) {
    case 'acr': {
        let esc = false;
        for (let i = 0; i < str.length; i++) {
            const c = str[i];
            if (esc) {
                esc = false;
                switch (c) {
                    case '%': {
                        out += "%";
                    } break;
                    default: {
                        out += "\\";
                        out += c;
                    } break;
                }
            } else if (c == '\\') {
                esc = true;
            } else {
                switch (c) {
                    case '$': {
                        out += "\\$";
                    } break;
                    case '%': {
                        out += ".*";
                    } break;
                    case '*': {
                        out += "\\*";
                    } break;
                    case '+': {
                        out += "\\+";
                    } break;
                    case '.': {
                        out += "\\.";
                    } break;
                    case '?': {
                        out += "\\?";
                    } break;
                    case '^': {
                        out += "\\^";
                    } break;
                    default: {
                        out += c;
                    } break;
                }
            }
        }
    } break;
    case 'default': {
        for (let i = 0; i < str.length; i++) {
            const c = str[i];
            switch (c) {
                default: {
                    out += c;
                } break;
            }
        }
    } break;
    case 'shell': {
        for (let i = 0; i < str.length; i++) {
            const c = str[i];
            switch (c) {
                case '$': {
                    out += "\\$";
                } break;
                case '(': {
                    out += "\\(";
                } break;
                case ')': {
                    out += "\\)";
                } break;
                case '*': {
                    out += ".*";
                } break;
                case '.': {
                    out += "\\.";
                } break;
                case '?': {
                    out += ".?";
                } break;
                case '[': {
                    out += "\\[";
                } break;
                case '\\': {
                    out += "\\\\";
                } break;
                case ']': {
                    out += "\\]";
                } break;
                case '^': {
                    out += "\\^";
                } break;
                default: {
                    out += c;
                } break;
            }
        }
    } break;
    case 'sql': {
        let esc = false;
        for (let i = 0; i < str.length; i++) {
            const c = str[i];
            if (esc) {
                esc = false;
                switch (c) {
                    case '%': {
                        out += "%";
                    } break;
                    case '_': {
                        out += "_";
                    } break;
                    default: {
                        out += "\\";
                        out += c;
                    } break;
                }
            } else if (c == '\\') {
                esc = true;
            } else {
                switch (c) {
                    case '$': {
                        out += "\\$";
                    } break;
                    case '%': {
                        out += ".*";
                    } break;
                    case '*': {
                        out += "\\*";
                    } break;
                    case '+': {
                        out += "\\+";
                    } break;
                    case '.': {
                        out += "\\.";
                    } break;
                    case '?': {
                        out += "\\?";
                    } break;
                    case '^': {
                        out += "\\^";
                    } break;
                    case '_': {
                        out += ".";
                    } break;
                    default: {
                        out += c;
                    } break;
                }
            }
        }
    } break;
    }
    return out
}

// STR, a default-syntax pattern, in the canonical form that algo_lib's parser
// and a JavaScript RegExp read alike, or null when the pattern is invalid.
export function regxNormalize(str: string): string | null {
    let out = ''
    let valid = true;
    let depth = 0;
    let term = false;
    let atom = false;
    let quant = '';
    let i = 0;
    while (i < str.length) {
        const c = str[i];
        let step = 1;
        let lit = false;
        if (c == '\\' && i + 1 < str.length) {
            const n = str[i + 1];
            if (regxMacroQ(n)) {
                out += regxMacroJs(n, false);
            } else {
                if (regxPunctQ(n)) {
                    out += '\\';
                }
                out += n;
            }
            step = 2;
            term = true;
            atom = true;
            quant = '';
        } else if (c == '[') {
            let j = i + 1;
            if (j < str.length && str[j] == '^') {
                j++;
            }
            let closed = false;
            while (j < str.length && !closed) {
                if (str[j] == '\\') {
                    j += 2;
                } else if (str[j] == ']') {
                    closed = true;
                } else {
                    j++;
                }
            }
            if (closed) {
                out += '[';
                let k = i + 1;
                if (str[k] == '^') {
                    out += '^';
                    k++;
                }
                while (k < j) {
                    const m = str[k];
                    if (m == '\\' && regxMacroQ(str[k + 1])) {
                        const n = str[k + 1];
                        out += regxMacroJs(n, true);
                        k += 2;
                    } else {
                        let lo = m;
                        let kk = k + 1;
                        if (m == '\\') {
                            lo = str[k + 1];
                            kk = k + 2;
                        }
                        let hi = lo;
                        if (kk + 1 < j && str[kk] == '-') {
                            const e = str[kk + 1];
                            if (e != '\\') {
                                hi = e;
                                kk = kk + 2;
                            } else if (!regxMacroQ(str[kk + 2])) {
                                hi = str[kk + 2];
                                kk = kk + 3;
                            }
                        }
                        if (hi < lo) {
                            hi = lo;
                        }
                        if (regxPunctQ(lo)) {
                            out += '\\';
                        }
                        out += lo;
                        if (hi != lo) {
                            out += '-';
                            if (regxPunctQ(hi)) {
                                out += '\\';
                            }
                            out += hi;
                        }
                        k = kk;
                    }
                }
                out += ']';
                step = j + 1 - i;
                term = true;
                atom = true;
                quant = '';
            } else {
                lit = true;
            }
        } else if (c == '(') {
            out += c;
            depth++;
            term = false;
            atom = false;
            quant = '';
        } else if (c == ')' && depth > 0) {
            out += c;
            depth--;
            term = true;
            atom = true;
            quant = '';
        } else if (c == ')') {
            lit = true;
        } else if (c == '|') {
            if (!term) {
                out += "()";
            }
            out += c;
            if (i + 1 == str.length || (str[i + 1] == ')' && depth > 0)) {
                out += "()";
            }
            term = false;
            atom = false;
            quant = '';
        } else if ((c == '*' || c == '+' || c == '?') && !atom) {
            lit = true;
        } else if (c == '*' || c == '+' || c == '?') {
            if (quant == '') {
                quant = c;
            } else {
                out = out.slice(0, -1);
                if (quant != c) {
                    quant = '*';
                }
            }
            out += quant;
        } else if (c == '.') {
            out += c;
            term = true;
            atom = true;
            quant = '';
        } else if (c == '^' || c == '$') {
            out += c;
            term = true;
            atom = false;
            quant = '';
        } else {
            lit = true;
        }
        if (lit) {
            if (regxPunctQ(c)) {
                out += '\\';
            }
            out += c;
            term = true;
            atom = true;
            quant = '';
        }
        i = i + step;
    }
    valid = valid && depth == 0;
    return valid ? out : null
}

// STR as the bytes algo_lib's Regx reads, one code unit per byte of its UTF-8
// encoding.  A byte of 0x80 or more becomes U+E080..U+E0FF, private-use code
// units that keep the order of the bytes and have no case.
export function regxBytes(str: string): string {
    let out = str
    if (/[^\x00-\x7f]/.test(str)) {
        out = ''
        for (const b of new TextEncoder().encode(str)) {
            out += String.fromCharCode(b < 0x80 ? b : 0xe000 + b)
        }
    }
    return out
}

// A compiled regx.  TEST is true when the regx matches SUBJECT.
export interface Regx {
    test(subject: string): boolean
}

// PATTERN, a regx of style STYLE, compiled to match what algo_lib's Regx
// matches: the whole subject when FULL, and any part of it otherwise.  Both
// sides read bytes, so a character outside ASCII counts as its UTF-8 length.
// FOLD ignores the case of ASCII letters, which algo_lib's Regx never does.
// Null when the pattern is invalid, which matches nothing.
export function regxCompile(pattern: string, style: RegxStyle, full: boolean, fold = false): Regx | null {
    const body = regxNormalize(regxRewrite(regxBytes(pattern), style))
    const re = body === null ? null : new RegExp(full ? '^(?:' + body + ')$' : body, fold ? 'si' : 's')
    return re === null ? null : { test: (subject: string) => re.test(regxBytes(subject)) }
}

// The literal start of STR, a pattern in the canonical form regxNormalize
// writes: the characters every match begins with.  The start ends at the first
// operator, and a literal that a * or ? makes optional is left out.  A pattern
// with an alternative outside every group has no common start, so its start
// is empty.
export function regxPrefix(str: string): string {
    let out = ''
    let depth = 0
    let alt = false
    let stop = false
    let i = 0
    while (i < str.length) {
        const c = str[i]
        let step = 1
        if (c == '\\' && i + 1 < str.length) {
            if (!stop) {
                out += str[i + 1]
            }
            step = 2
        } else if (c == '[') {
            stop = true
            let j = i + 1
            while (j < str.length && str[j] != ']') {
                j += str[j] == '\\' ? 2 : 1
            }
            step = j + 1 - i
        } else if (c == '(') {
            stop = true
            depth++
        } else if (c == ')') {
            depth--
        } else if (c == '|') {
            stop = true
            alt = alt || depth == 0
        } else if (c == '*' || c == '?') {
            if (!stop) {
                out = out.slice(0, -1)
            }
            stop = true
        } else if (c == '+' || c == '.' || c == '^' || c == '$') {
            stop = true
        } else if (!stop) {
            out += c
        }
        i = i + step
    }
    return alt ? '' : out
}

// The regx styles a backslash escapes in (amcdb.regxstyle esc:Y).
export type RegxQuoteStyle = 'acr' | 'sql'

// STR as a pattern of regx style STYLE that matches STR alone.  A backslash
// goes before each character that the style reads as an operator, and the
// rest stays as written.
export function regxQuote(str: string, style: RegxQuoteStyle): string {
    let out = ''
    for (const c of str) {
        let op = false
        switch (style) {
        case 'acr':
            op = c === '%' || c === '(' || c === ')' || c === '[' || c === '\\' || c === '|'
            break
        case 'sql':
            op = c === '%' || c === '(' || c === ')' || c === '[' || c === '\\' || c === '_' || c === '|'
            break
        }
        out += op ? '\\' + c : c
    }
    return out
}
